style.css:
@-moz-document url-prefix("https://www.pinterest."), regexp("^https?:\/\/(www|[a-z]{2}).pinterest.(com(.(au|mx))?|(co.uk)|ca|se|jp|fr|de|es|ch|dk|nz|ch|ie|pt|ru|it)\/.*") {
:root {
        --by_ix-color_dark0: #000000;
        --by_ix-color_dark1: #ffffff;
        --by_ix-color_dark2: #ffffff;
        --by_ix-color_dark3: #ffffff;
        --by_ix-color_dark4: #aab2b9;
        --by_ix-color_dark5: #ffffff;
        --by_ix-color_dark6: #ffffff;
        --by_ix-color_dark7: #aab2b9;
        --by_ix-color_white0: #ffffff;
        --by_ix-color_white1: #aab2b9;
        --by_ix-color_white2: #d4d4d4;
        --by_ix-color_white3: #a3a3a3;
        --by_ix-color_white4: #aab2b9;
        --by_ix-color_white5: #aab2b9;
        --by_ix-color_pink0: #edccd7;
        --by_ix-color_pink1: #edccd7;
        --by_ix-color_pink2: #f2dce4;       
        --g-colorGray0: #edccd7;
        --color-border-container: #edccd7;
        --color-text-icon-default: #edccd7;
    }
    
    /*---------- BODY & TEXTOS (NEGRO A GRIS) ----------*/
        
    a {
        color: var(--by_ix-color_white0) !important;
    }
    a:focus, a:hover {
        color: var(--by_ix-color_white2);
    }
    input[type="text"] {
        color: var(--by_ix-color_white1) !important;
    }
    body, p, span, h1, h2, h3, h4, h5, h6 {
        color: var(--by_ix-color_dark4);
    }
    h3, h5 {
        color: var(--by_ix-color_white0) !important;
    }
    body, div[data-test-id="pin-builder"] {
        background: var(--by_ix-color_dark2) !important;
        height: auto !important;
    }
    :focus {
        outline: 1px auto var(--by_ix-color_dark3);
    }
    *::-webkit-scrollbar {
        width: 7px !important;
        height: 7px !important;
        background: var(--by_ix-color_dark1) !important;
        border: 1px solid var(--by_ix-color_dark1) !important;
    }
    *::-webkit-scrollbar-thumb {
        min-height: 28px !important;
        background: var(--by_ix-color_pink1) !important;
        border-radius: 10px;
    }
    
    /*---------- QUITANDO RECUADROS ROSAS EN PINES/IMÁGENES ----------*/
    div[data-test-id="pin-card"],
    div[data-test-id="card-actions"],
    div[data-test-id="pin-container"],
    div[data-test-id="board-card"] {
        background-color: var(--by_ix-color_dark2) !important;
        background: var(--by_ix-color_dark2) !important;
        box-shadow: none !important;
    }
    
    /*---------- HEADER & BARRA SUPERIOR SÓLIDA ----------*/
    
    svg > path[d*="M12 12c0 5.123 3.211 9.497 7.73 11.218-.11-.937-.227-2.482.025"] {
        fill: var(--by_ix-color_pink0) !important;
        color: var(--by_ix-color_pink0) !important;
    }
    header nav {
        color: var(--by_ix-color_pink0) !important;
    }
    div[data-test-id="header-menu"] {
        top: 18px !important;
    }
    div[data-test-id="header-background"],
    header[role="banner"] {
        background-color: var(--by_ix-color_dark2) !important;
        background: var(--by_ix-color_dark2) !important;
        opacity: 1 !important;
    }
    div[data-test-id="user-menu"] {
        background-color: var(--by_ix-color_dark2);
    }
    div[data-test-id="header-search-bar"] {
        background-color: var(--by_ix-color_dark5);
    }
    div[data-test-id="header-container"] {
        border: 1px solid var(--by_ix-color_dark3);
        background-color: var(--by_ix-color_dark2) !important;
    }
    
    div[data-test-id="header-logo"] a, 
    div[data-test-id="header-logo"] svg,
    a[href="/"] svg {
        color: var(--by_ix-color_pink0) !important;
        fill: var(--by_ix-color_pink0) !important;
    }

    .ProPartnerHeaderMenuList .proPartnerHeaderMenuItem:hover {
        background-color: var(--by_ix-color_dark4) !important;
    }
    
    /*---------- CATEGORÍAS SUPERIORES A #a3a3a3 ----------*/
    div[data-root-margin="more-ideas-tabs"] a,
    div[data-root-margin="more-ideas-tabs"] span,
    div[data-root-margin="more-ideas-tabs"] div,
    div[data-test-id="search-tab-bar"] a,
    div[data-test-id="search-tab-bar"] span {
        color: #a3a3a3 !important;
    }

    /*---------- TÍTULOS Y TEXTOS DE LA PÁGINA DE PERFIL Y NOMBRES DE TABLEROS A #a3a3a3 ----------*/
    div[data-test-id="profile-header"] h1,
    div[data-test-id="profile-header"] div,
    div[data-test-id="profile-header"] span,
    div[data-test-id="saved-feed-container"] h1,
    div[data-test-id="saved-feed-container"] h2,
    div[data-test-id="saved-feed-container"] span,
    div[data-test-id="board-card"] div,
    div[data-test-id="board-card"] span,
    div[data-grid-item] div,
    div[data-grid-item] span,
    h2[class*="GrowthUnauthServer"],
    div[data-test-id="grid-Container"] a div,
    div[data-test-id="grid-Container"] a span {
        color: #a3a3a3 !important;
    }

    /*---------- SEARCH & PROFILE ----------*/

    div[data-test-id="search-container"] {
        background-color: var(--by_ix-color_dark3) !important;
    }
    div[data-test-id="search-bar"] {
        height: 30px !important;
    }
    div[data-test-id="search-filter"] {
        height: 28px !important;
    }
    div[data-test-id="search-tab-bar"] {
        background-color: var(--by_ix-color_dark7) !important;
    }
    div[data-test-id="profile-header"] {
        background: var(--by_ix-color_dark5);
        margin: 0% 32%;
        padding: 10px 0px 20px 0px;
        border-top-left-radius: 0px;
        border-top-right-radius: 0px;
        border-bottom-left-radius: 32px;
        border-bottom-right-radius: 32px;
    }
    div[data-test-id="profile-stats"] {
        margin-bottom: 0px !important;
    }
    div[data-test-id="profile-avatar"] {
        border: 2px solid var(--by_ix-color_pink2) !important;
    }
    div[data-test-id="profile-name"] {
        font-weight: bold !important;
    }
    
    /*---------- CONTENT, UPLOAD & LOGIN ----------*/
    
    div[data-root-margin="more-ideas-tabs"] {
        background-color: var(--by_ix-color_dark7) !important;
    }
    
    div[data-test-id="closeup-lego-container"] {
        background: transparent !important;
        background-color: transparent !important;
        box-shadow: var(--by_ix-color_pink2) 0px 0px 25px 8px !important;
        margin-bottom: 20px;
        border-radius: 24px;
    }

    div[data-test-id="closeup-lego-container"] > div {
        background-color: var(--by_ix-color_dark2) !important;
        border-radius: 24px;
    }

    div[aria-label="reaction"] {
        background-color: var(--by_ix-color_dark5) !important;
    }
    div[aria-label="reaction"]:hover {
        background-color: var(--by_ix-color_dark3) !important;
    }
    div[data-test-id="related-modules-header"] {
        margin-bottom: 20px;
    }
    button[data-test-id="board-dropdown-select-button"] {
        background-color: var(--by_ix-color_dark3) !important;
        color: var(--by_ix-color_white1);
    }
    button[data-test-id="board-dropdown-select-button"] span {
        color: var(--by_ix-color_white1) !important;
    }
    .react-datepicker {
        background-color: var(--by_ix-color_dark1) !important;
    }
    .react-datepicker__day:hover {
        background-color: var(--by_ix-color_dark3);
    }
    div[role="list"], option {
        background-color: var(--by_ix-color_dark1);
    }
    div[data-test-id="login-modal-default"] {
        background-color: var(--by_ix-color_dark4) !important;
    }    
    div[data-test-id="login-modal-default"] h1 {
        color: var(--by_ix-color_white1) !important;
    }

    /*---------- ICONOS DE LA BARRA LATERAL IZQUIERDA ----------*/
    nav, aside, div[data-test-id="app-content-wrapper"] nav {
        background-color: transparent !important;
        background: transparent !important;
        box-shadow: none !important;
    }
    nav svg, nav path, 
    aside svg, aside path,
    [data-test-id="app-content-wrapper"] nav svg, 
    [data-test-id="app-content-wrapper"] nav path {
        color: var(--by_ix-color_pink0) !important;
        fill: var(--by_ix-color_pink0) !important;
    }

    /*---------- MODAL DEL PIN EN GRANDE: TEXTO A #a3a3a3 E ICONOS SUPERIORES EN ROSA ----------*/
    div[data-test-id="closeup-lego-container"] h1,
    div[data-test-id="closeup-lego-container"] h2,
    div[data-test-id="closeup-lego-container"] h3,
    div[data-test-id="closeup-lego-container"] h4,
    div[data-test-id="closeup-lego-container"] p,
    div[data-test-id="closeup-lego-container"] span,
    div[data-test-id="closeup-lego-container"] div {
        color: #a3a3a3;
    }

    div[data-test-id="closeup-lego-container"] button svg,
    div[data-test-id="closeup-lego-container"] button path,
    div[data-test-id="closeup-lego-container"] [role="button"] svg,
    div[data-test-id="closeup-lego-container"] [role="button"] path {
        color: var(--by_ix-color_pink0) !important;
        fill: var(--by_ix-color_pink0) !important;
    }
}
